function drawBackground(){
  const sky = ctx.createLinearGradient(0, 0, 0, H);
  sky.addColorStop(0, '#858b66');
  sky.addColorStop(0.42, '#9f9d72');
  sky.addColorStop(0.43, '#6a735a');
  sky.addColorStop(1, '#2c332e');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, W, H);

  ctx.globalAlpha = 0.2;
  for (let i = 0; i < 6; i++) {
    ctx.fillStyle = '#eadbb4';
    ctx.beginPath();
    ctx.arc(90 + i * 170, 80 + (i % 2) * 30, 72, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;

  for (let i = 0; i < 18; i++) {
    const x = ((i * 125 - scenery * 0.24) % (W + 180)) - 90;
    const h = 50 + (i * 37 % 75);
    const trunkH = h - 10;
    ctx.fillStyle = '#384a3d';
    ctx.fillRect(x, 236 - trunkH, 11, trunkH);
    ctx.fillStyle = '#3d4d3f';
    ctx.beginPath();
    ctx.moveTo(x - 28, 245 - trunkH);
    ctx.lineTo(x + 5, 160 - trunkH);
    ctx.lineTo(x + 34, 245 - trunkH);
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(x - 20, 230 - trunkH);
    ctx.lineTo(x + 6, 150 - trunkH);
    ctx.lineTo(x + 30, 230 - trunkH);
    ctx.fill();
  }

  for (let i = 0; i < 5; i++) {
    const x = ((i * 240 - scenery * 0.34) % (W + 260)) - 130;
    ctx.fillStyle = '#707062';
    ctx.fillRect(x, 247, 62, 46);
    ctx.fillStyle = '#4a514b';
    ctx.fillRect(x + 8, 255, 16, 21);
    ctx.fillRect(x + 35, 260, 12, 12);
    ctx.fillStyle = '#3a3d38';
    ctx.fillRect(x - 10, 293, 80, 5);
  }

  ctx.fillStyle = '#5d5f49';
  ctx.fillRect(0, 315, W, 120);
  ctx.fillStyle = '#4b4e42';
  ctx.fillRect(0, 330, W, 100);
  ctx.fillStyle = '#312e29';
  ctx.fillRect(0, 346, W, 70);
  ctx.fillStyle = '#b8b38c';
  ctx.fillRect(0, 343, W, 4);

  for (let x = -60; x < W + 80; x += 112) {
    const roadX = x - (scenery * 0.8) % 112;
    ctx.fillStyle = '#d2c399';
    ctx.fillRect(roadX, 370, 52, 4);
    ctx.fillStyle = '#2f322d';
    ctx.fillRect(roadX + 25, 410, 25, 5);
  }

  for (let i = 0; i < 6; i++) {
    const x = ((i * 220 - scenery * 0.7) % (W + 260)) - 110;
    ctx.fillStyle = '#4a4d46';
    ctx.fillRect(x, 190, 5, 120);
    ctx.fillStyle = '#5d6253';
    ctx.fillRect(x - 34, 208, 72, 3);
    ctx.fillStyle = '#4d5148';
    ctx.fillRect(x - 18, 214, 14, 62);
  }

  for (let i = 0; i < 34; i++) {
    const x = (i * 91 - scenery * 1.25 + W) % W;
    const y = 410 + (i * 23 % 70);
    ctx.fillStyle = '#8d8669';
    ctx.fillRect(x, y, 2, 2);
  }
}

function drawVan(){
  const x = 60, y = 322;
  ctx.save();
  ctx.fillStyle = '#10171666';
  ctx.beginPath();
  ctx.ellipse(x + 72, 408, 84, 10, 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#4b5b4f';
  ctx.fillRect(x + 2, y + 12, 145, 62);
  ctx.fillStyle = '#33433d';
  ctx.fillRect(x + 12, y + 8, 52, 44);
  ctx.fillRect(x + 72, y + 8, 44, 40);
  ctx.fillRect(x + 116, y + 30, 24, 30);

  ctx.fillStyle = '#9ca69a';
  ctx.fillRect(x + 34, y + 10, 24, 22);
  ctx.fillStyle = '#d4d0b6';
  ctx.fillRect(x + 68, y + 15, 22, 4);
  ctx.fillStyle = '#d9d1b7';
  ctx.beginPath();
  ctx.arc(x + 78, y + 38, 8, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#4e5c4f';
  ctx.beginPath();
  ctx.arc(x + 78, y + 38, 4, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#1b1d1f';
  ctx.fillRect(x - 4, y + 66, 158, 7);
  ctx.fillStyle = '#d9a24d';
  ctx.fillRect(x + 2, y + 52, 15, 8);
  ctx.fillStyle = '#d76d50';
  ctx.fillRect(x + 132, y + 56, 15, 7);

  ctx.fillStyle = '#d2d0b4';
