+/* Weathered field-manual palette and square, pixel-era HUD panels. */
+:root{--ink:#252923;--panel:#34382f;--muted:#a19f89;--paper:#e2dcc4;--orange:#c67b4d;--lime:#a9b477;--line:rgba(224,218,191,.22)}
+body{background-color:#222720;background-image:radial-gradient(ellipse at 50% 20%,#42473b 0,#292e27 50%,#1d221e 100%);font-family:'DM Mono',monospace}
+.brand b,.mission-hud b,.panel-screen h2,.deploy-card,.primary-btn,.quiet-btn{font-family:'Barlow Condensed',monospace}
+.brand-mark,.game-frame,.mission-icon,.pause-btn,.pause-pop,.carrier-health,.credits,.deploy-card,.primary-btn,.recruit-card{border-radius:0!important}
+.game-frame{border:3px solid #676650;box-shadow:0 12px 0 #171b17,0 24px 60px #0008;background:#777965}
+canvas{image-rendering:pixelated}
+.screen-shade{background:linear-gradient(90deg,rgba(27,31,26,.76),rgba(27,31,26,.42) 51%,rgba(27,31,26,.08))}
+.mission-hud,.carrier-health,.credits,.deploy-card,.pause-pop{background:rgba(39,44,37,.94);border:1px solid #85816a;box-shadow:3px 3px 0 rgba(26,29,25,.75)}
+.mission-icon{background:#62664f;color:#e3ddc4;border:1px solid #a69d79}
+.mission-hud small,.route-track-label,.health-title,.credits small,.card-role,.tipline,.footer{font-family:'DM Mono',monospace;letter-spacing:1px}
+.route-track .track,.health-track{border:1px solid #77735e;background:#292d27;border-radius:0}
+.route-track .track i,.health-track i{border-radius:0;background:#a9b477}
+.pause-btn{background:#373d34;color:#e5ddc1;border:1px solid #89836b;box-shadow:2px 2px 0 #1b201c}
+.credits{color:#e5ddc1}.credits>span{color:#d39a61}
+.deploy-card{background:#42463a;color:#e4ddc4;border-color:#817d65;box-shadow:2px 2px 0 #20241f}
+.deploy-card:hover,.deploy-card.selected{background:#59604a;border-color:#d0bd87}
+.deploy-card.disabled{filter:saturate(.55);opacity:.65}
+.card-icon{border-radius:0;background:#676950;color:#e6d9ae}
+.card-cost{border-top:1px solid rgba(226,220,196,.2)}
+.primary-btn{background:#b9784d;color:#201f19;border:2px solid #e0ad75;box-shadow:3px 3px 0 #392a20}
+.primary-btn:hover{background:#d38b57}
+.quiet-btn{color:#d3cbb0}
+.panel-screen{background:rgba(39,43,36,.86);border-left:4px solid #c17b4f}
+.panel-screen p{color:#ccc5ad}
+.recruit-card{background:#343a31;border:1px solid #78765f}
+.footer{color:#8f907c}
